-- ── OpenBI Portfolio Demo: Massive PostgreSQL Seed Data ──

CREATE TABLE benchmark_returns (benchmark_id SERIAL PRIMARY KEY, benchmark_name VARCHAR(100) NOT NULL UNIQUE, asset_class VARCHAR(50) NOT NULL);

CREATE TABLE funds (fund_id SERIAL PRIMARY KEY, ticker VARCHAR(10) NOT NULL UNIQUE, fund_name VARCHAR(100) NOT NULL, asset_class VARCHAR(50) NOT NULL, benchmark_id INT REFERENCES benchmark_returns(benchmark_id), management_fee_bps INT NOT NULL);

CREATE TABLE portfolios (portfolio_id SERIAL PRIMARY KEY, client_name VARCHAR(100) NOT NULL, client_type VARCHAR(50) NOT NULL, inception_date DATE NOT NULL);

CREATE TABLE daily_nav (nav_id SERIAL PRIMARY KEY, trade_date DATE NOT NULL, fund_id INT REFERENCES funds(fund_id), nav_per_share NUMERIC(10,4) NOT NULL, total_aum NUMERIC(15,2) NOT NULL, daily_net_flow NUMERIC(15,2) NOT NULL DEFAULT 0);
CREATE INDEX idx_nav_date ON daily_nav(trade_date);
CREATE INDEX idx_nav_fund ON daily_nav(fund_id);

-- Generating Daily NAV (5 Years * ~250 trading days * 4 funds = ~5,000 rows)

CREATE TABLE client_transactions (tx_id SERIAL PRIMARY KEY, tx_date DATE NOT NULL, portfolio_id INT REFERENCES portfolios(portfolio_id), fund_id INT REFERENCES funds(fund_id), tx_type VARCHAR(20) NOT NULL, amount NUMERIC(15,2) NOT NULL);
CREATE INDEX idx_tx_date ON client_transactions(tx_date);
CREATE INDEX idx_tx_port ON client_transactions(portfolio_id);

